pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // -------- Progress of the packing process --------
    let progress = step_index as f64 / total_items as f64;

    // -------- Core score --------
    let mut score = post_residual as f64;

    // Quadratic penalty on residual, softened towards the end
    let quad_penalty = (post_residual as f64).powi(2)
        * (1.0 - progress).powi(2)
        * 0.02;
    score -= quad_penalty;

    // Distance from the mean residual
    let diff_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_mean * 0.15 + diff_mean.powi(2) * 0.001;

    // Extra penalty if residual is far above the mean
    if diff_mean > 5.0 {
        score += (diff_mean - 5.0) * 0.02;
    }

    // Tight‑packing bias
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_ratio).powi(2) * 10.0;
    if residual_ratio > 0.75 {
        score += 8.0;
    }
    if residual_ratio > 0.9 {
        score -= 6.0;
    }

    // Bonus/penalty based on residual extremes
    if residual_ratio < 0.2 {
        score += 5.0;
    } else if residual_ratio > 0.8 {
        score -= 3.0;
    }

    // -------- Look‑ahead for the next item --------
    if next_item_size > 0 {
        if bin_residual >= item_size + next_item_size {
            let after_both = bin_residual - item_size - next_item_size;
            let diff_both = (after_both as f64 - mean_residual).abs();
            score -= diff_both * 0.4;
            score -= after_both as f64 * 0.015;
        } else {
            let missing = next_item_size - bin_residual;
            score += 0.5 * missing as f64;
            let ratio = next_item_size as f64 / bin_capacity as f64;
            score += ratio * 12.0;
            // Extra penalty for large gaps
            if missing > 20 {
                score += missing as f64 * 0.3;
            }
        }
    }

    // -------- Open‑bin penalty --------
    score += (open_bins_count as f64) * 0.6;

    // -------- Fitting‑bin count --------
    if fitting_bins_count > 3 {
        score += 2.0; // encourage new bin if many fit
    } else if fitting_bins_count > 1 {
        score -= (fitting_bins_count as f64 - 1.0) * 1.8;
    } else {
        score -= 350.0;
    }

    // -------- New‑bin handling --------
    if bin_residual == bin_capacity {
        if open_bins_count > 4 {
            score += 12.0;
        }
        if post_residual < mean_residual + 2.5 {
            score -= 9.0;
        } else if post_residual > mean_residual + 7.0 {
            score += 7.0;
        }
        let new_item_ratio = item_size as f64 / bin_capacity as f64;
        if new_item_ratio > 0.85 {
            score -= 4.0;
        }
    }

    // -------- Progress bias --------
    if progress < 0.1 {
        score += post_residual as f64 * 0.03;
    } else if progress > 0.9 {
        score -= post_residual as f64 * 0.03;
    }

    // -------- Final adjustments --------
    let item_ratio = item_size as f64 / bin_capacity as f64;
    score -= (1.0 - item_ratio) * post_residual as f64 * 0.03;

    if residual_ratio > 0.6 {
        score += 6.0;
    }

    if diff_mean > 7.0 {
        score += 3.5;
    }

    if fitting_bins_count == 1 {
        score -= post_residual as f64 * progress;
    }

    // Bonus for packing a large item into a well‑filled bin
    if item_ratio > 0.7 && residual_ratio > 0.7 {
        score += 3.0;
    }

    score
}

