pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Polynomial coupling of residual and stream progress
    score -= (post_residual as f64).powi(2) * progress * (1.0 - progress);

    // Penalize large residual when many bins are open
    score -= (open_bins_count as f64).powi(2) * (post_residual as f64) * (1.0 - progress);

    // Encourage bins close to the mean residual
    score -= ((post_residual as f64) - mean_residual).powi(2);

    // Penalize if the next item cannot fit in the remaining space
    if next_item_size > 0 {
        let future_penalty = ((next_item_size as f64) - (post_residual as f64)).max(0.0);
        score -= future_penalty.powi(2) * progress;
    }

    // Reward the bin if it is the sole candidate that can fit the item
    if fitting_bins_count == 1 {
        score -= (post_residual as f64) * progress;
    }

    // New bin candidate: penalize opening a new bin early in the stream
    if bin_residual == bin_capacity {
        let new_bin_penalty = (1.0 - progress).powi(3) * (open_bins_count as f64);
        score += new_bin_penalty * (post_residual as f64);
    }

    score
}

